/// Microseconds since the Unix epoch of 1900-01-01T00:00Z.
const EPOCH_MICROS: i64 = -2_208_988_800_000_000;

/// The moment of a table entry.
fn instant(minutes: u32) -> UtcInstant {
    UtcInstant::from_micros(EPOCH_MICROS + i64::from(minutes) * 60_000_000)
}

/// The last jie at or before `moment`: its index (0 小寒 … 11 大雪), the Gregorian year it
/// belongs to and its moment; `None` outside the table.
pub(crate) fn jie_before(moment: UtcInstant) -> Option<(usize, i32, UtcInstant)> {
    let (y, ..) = moment.civil();
    for year in [y, y - 1] {
        let index = usize::try_from(year - FIRST_YEAR).ok()?;
        let Some(row) = JIE.get(index) else { continue };
        if let Some(i) = (0..12).rev().find(|&i| instant(row[i]) <= moment) {
            return Some((i, year, instant(row[i])));
        }
    }
    None
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::chinese::calendar::jie_of_year;

    use crate::test_kernel::full_kernel as kernels;

    fn minutes(jd: f64) -> u32 {
        ((jd - 2_415_020.5) * 1440.0).round() as u32
    }

    #[test]
    #[ignore = "generates the table: cargo test --release jie_table::tests::print_table -- --ignored --nocapture"]
    fn print_table() {
        let kernels = kernels().expect("kernels/de440s.bsp");
        for year in FIRST_YEAR..=2100 {
            let row = jie_of_year(&kernels, year).unwrap().map(minutes);
            let cells: Vec<String> = row.iter().map(u32::to_string).collect();
            println!("    [{}], // {year}", cells.join(", "));
        }
    }

    #[test]
    fn the_table_matches_the_search() {
        let Some(kernels) = kernels() else { return };
        assert_eq!(JIE.len(), 201);
        for (i, row) in JIE.iter().enumerate() {
            let year = FIRST_YEAR + i as i32;
            assert_eq!(
                *row,
                jie_of_year(&kernels, year).unwrap().map(minutes),
                "{year}"
            );
        }
    }

    #[test]
    fn known_jie() {
        // 立春 2024: 2024-02-04T08:27Z (16:27 Beijing time).
        let moment = UtcInstant::parse("2024-02-04T08:28:00Z").unwrap();
        let (index, year, at) = jie_before(moment).unwrap();
        assert_eq!((index, year), (1, 2024));
        assert!(moment.seconds_since(&at) < 120.0, "{}", at.isoformat());
        // Early January belongs to 大雪 of the year before.
        let (index, year, _) =
            jie_before(UtcInstant::parse("2024-01-01T00:00:00Z").unwrap()).unwrap();
        assert_eq!((index, year), (11, 2023));
        assert!(jie_before(UtcInstant::parse("1899-12-31T00:00:00Z").unwrap()).is_none());
    }
}
